// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring, Easing } from '../remotionShim';
// Google Fonts
import { makeLoadFont } from '../googleFonts';
const loadManrope = makeLoadFont('Manrope');
const { fontFamily: manropeFamily } = loadManrope();



export type MinimalClockAnimationProps = Record<string, any>;

const MinimalClockAnimation: React.FC<MinimalClockAnimationProps> = ({
  backgroundColor = "#FAFAFA",
  transparentBackground = false,
  durationInSeconds = 4,
  clockColor = "#1A1A1A",
  accentColor = "#3B82F6",
  outlineColor = "#E5E5E5",
  shadowColor = "rgba(0,0,0,0.06)",
  labelText = "24 hours",
  endText = "A full day gone",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  
  const totalFrames = fps * durationInSeconds;
  
  // The clock animation ends 1 second before the total duration to allow the end text to shine
  const animDuration = totalFrames - fps;
  
  // Timing variables
  const startAnimFrame = 20;
  const endAnimFrame = animDuration;
  
  // Smooth easing for the rapid clock spin
  const spinProgress = interpolate(
    frame,
    [startAnimFrame, endAnimFrame],
    [0, 1],
    {
      easing: Easing.bezier(0.25, 0.1, 0.25, 1),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // Rotation Math (24 hours = 2 loops for hour hand, 24 loops for minute hand)
  const minuteRotation = spinProgress * 24 * 360; 
  const hourRotation = spinProgress * 2 * 360;    
  
  // Progress Ring Math
  const radius = 48;
  const circumference = 2 * Math.PI * radius;
  const ringOffset = circumference - (spinProgress * circumference);

  // Global Camera Scale (slow, constant push-in)
  const cameraScale = interpolate(frame, [0, totalFrames], [1, 1.04], { extrapolateRight: "clamp" });

  // Entry Animations
  const clockScale = spring({ fps, frame, config: { damping: 14, mass: 0.8 }, delay: 5 });
  const clockOpacity = interpolate(frame, [5, 15], [0, 1], { extrapolateRight: "clamp" });

  const labelOpacity = interpolate(frame, [15, 30], [0, 1], { extrapolateRight: "clamp" });
  const labelY = interpolate(frame, [15, 30], [15, 0], { 
    extrapolateRight: "clamp", 
    easing: Easing.out(Easing.cubic) 
  });

  // End Text Animations
  const endOpacity = interpolate(frame, [animDuration - 5, animDuration + 15], [0, 1], { extrapolateRight: "clamp" });
  const endY = interpolate(frame, [animDuration - 5, animDuration + 15], [10, 0], { 
    extrapolateRight: "clamp", 
    easing: Easing.out(Easing.cubic) 
  });

  // Responsive sizing (supports portrait, square, or landscape gracefully)
  const baseSize = Math.min(width, height);
  const clockSize = baseSize * 0.55;

  return (
    <AbsoluteFill style={{ 
      backgroundColor: bgColor, 
      fontFamily: manropeFamily, 
      justifyContent: 'center', 
      alignItems: 'center',
      transition: "none",
    }}>
      
      {/* Global Camera Scale Wrapper */}
      <div style={{
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        transform: `scale(${cameraScale})`,
        width: "100%",
        height: "100%",
        transition: "none",
      }}>
        
        {/* Clock Container */}
        <div style={{
          width: clockSize,
          height: clockSize,
          opacity: clockOpacity,
          transform: `scale(${clockScale})`,
          filter: `drop-shadow(0px 20px 40px ${shadowColor})`,
          position: "relative",
          transition: "none",
        }}>
          <svg
            width="100%"
            height="100%"
            viewBox="0 0 100 100"
            style={{ overflow: "visible", transition: "none" }}
          >
            {/* Background Base */}
            <circle cx="50" cy="50" r="49" fill={backgroundColor} style={{ transition: "none" }} />
            
            {/* Soft Outline */}
            <circle cx="50" cy="50" r={radius} stroke={outlineColor} strokeWidth="0.5" fill="none" style={{ transition: "none" }} />
            
            {/* Clock Ticks */}
            {[...Array(12)].map((_, i) => {
               const isQuarter = i % 3 === 0;
               return (
                 <line
                    key={i}
                    x1="50" y1={isQuarter ? "3.5" : "5"}
                    x2="50" y2={isQuarter ? "9" : "8"}
                    stroke={outlineColor}
                    strokeWidth={isQuarter ? "1" : "0.5"}
                    strokeLinecap="round"
                    transform={`rotate(${i * 30} 50 50)`}
                    style={{ transition: "none" }}
                 />
               );
            })}

            {/* Radial Progress Ring */}
            <circle
              cx="50" cy="50" r={radius}
              stroke={accentColor}
              strokeWidth="1.5"
              fill="none"
              strokeDasharray={circumference}
              strokeDashoffset={ringOffset}
              strokeLinecap="round"
              transform="rotate(-90 50 50)"
              style={{ transition: "none" }}
            />

            {/* Hour Hand */}
            <line
              x1="50" y1="50" x2="50" y2="26"
              stroke={clockColor}
              strokeWidth="2.5"
              strokeLinecap="round"
              transform={`rotate(${hourRotation} 50 50)`}
              style={{ transition: "none" }}
            />

            {/* Minute Hand */}
            <line
              x1="50" y1="50" x2="50" y2="12"
              stroke={clockColor}
              strokeWidth="1.2"
              strokeLinecap="round"
              transform={`rotate(${minuteRotation} 50 50)`}
              style={{ transition: "none" }}
            />

            {/* Center Pin */}
            <circle cx="50" cy="50" r="2.5" fill={clockColor} style={{ transition: "none" }} />
            <circle cx="50" cy="50" r="0.8" fill={backgroundColor} style={{ transition: "none" }} />
          </svg>
        </div>

        {/* Labels Container */}
        <div style={{
          marginTop: baseSize * 0.1,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          transition: "none",
        }}>
          {/* Top Label */}
          <div style={{
            opacity: labelOpacity,
            transform: `translateY(${labelY}px)`,
            color: clockColor,
            fontSize: baseSize * 0.045,
            fontWeight: 500,
            letterSpacing: "0.02em",
            marginBottom: baseSize * 0.015,
            transition: "none",
          }}>
            {labelText}
          </div>

          {/* End Label */}
          <div style={{
            opacity: endOpacity * 0.5,
            transform: `translateY(${endY}px)`,
            color: clockColor,
            fontSize: baseSize * 0.03,
            fontWeight: 500,
            letterSpacing: "0.01em",
            transition: "none",
          }}>
            {endText}
          </div>
        </div>

      </div>
    </AbsoluteFill>
  );
};

export default MinimalClockAnimation;